<?php require_once __DIR__ . '/../includes/auth.php'; requireAdmin(); $rows=getDB()->query('SELECT r.*,a.username AS referrer,b.username AS referee FROM referrals r JOIN users a ON a.id=r.referrer_id JOIN users b ON b.id=r.referee_id ORDER BY r.created_at DESC')->fetchAll(); $pageTitle='Referrals'; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/_header.php'; ?><div class="page-title"><span class="eyebrow">NETWORK AUDIT</span><h1>Referrals</h1></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Referrer</th><th>Member</th><th>Level</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['referrer']) ?></td><td><?= e($r['referee']) ?></td><td>L<?= e($r['level']) ?></td><td><?= e(formatDate($r['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include __DIR__.'/_footer.php'; ?></body></html>
